def classify(n):
    if n > 0:
        return "positive"
    elif n < 0:
        return "negative"
    else:
        return "zero"


def main():
    number = int(input("Enter a number: "))
    result = classify(number)
    print(f"That number is {result}.")


if __name__ == "__main__":
    main()
